.bm-live-website-btn__dot {
  --shadow-m:  0 0 4px 2px rgba(255, 255, 255, 0.2);
  --shadow-xl: 0 0 16px 8px rgba(255, 255, 255, 0.8);
	--animation-duration-up: 1.2s;
  --shadow-light: var(--shadow-m);
  --shadow-heavy: var(--shadow-xl);
  --animation-iteration-count: infinite;
  --animation-direction: alternate;
  --animation-timing-function-up: linear;
}

/* Define the animation for the first child */
.bm-live-website-btn__dot{
  animation: glow var(--animation-duration-up) var(--animation-iteration-count) var(--animation-timing-function-up) var(--animation-direction);
}

/* Define the animations ending point for the first child */
@keyframes glow {
  0% {
    box-shadow: var(--shadow-light);
  }
  100% {
    box-shadow: var(--shadow-heavy);
  }
}

@media (min-width:767px) {

.bm-span2-media-item--alt:first-child {
  grid-column: span 1;
  aspect-ratio: 4/3;
}  

.bm-span2-media-item--alt:last-child {
  grid-column: span 2;
  aspect-ratio: 16/9;
}

}

.bm-portfolio-single-testimonial-3__review::before {
  content: ' " ';
  position: absolute;
  top: calc(-1 * (var(--space-xl) * 1.3));
  font-size: calc(var(--text-xxl) * 3);
  line-height: 1;
  left: calc(-1 * (var(--space-xs) / 1.4));

}
